package hostconn

import (
	"context"

	"github.com/jackc/pgx/v5"
	"github.com/liubing0806/allowops/internal/store"
)

// Fixed-shape statements of this package are generated by sqlc from
// internal/store/queries/hostconn.sql. LISTEN is the only hand-written
// statement: the channel name is an identifier and cannot be a bind parameter.

// listen subscribes the dedicated listener connection to gateway notifications.
func listen(ctx context.Context, l *pgx.Conn) error {
	_, err := l.Exec(ctx, "LISTEN "+store.NotificationChannel)
	return err
}
